pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.deal(actor, amount);
        uint256 before = c.Acc(actor).balance;
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        assertEq(c.Acc(actor).balance - before, amount);
    }
