pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 10 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(block.timestamp + 1);

        // General rule: every Ether the contract holds is accounted for as a
        // recorded balance in Acc; since only this actor interacted, the
        // recorded balance must equal the contract's actual balance.
        assertTrue(address(c).balance == c.Acc(actor).balance);
    }
}

