pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint128 depositAmount, uint128 withdrawAmount, address actor, uint64 waitTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 d = bound(uint256(depositAmount), 1 ether, 1000 ether);
        // strictly partial withdrawal: 0 < w < d
        uint256 w = bound(uint256(withdrawAmount), 1, d - 1);
        vm.warp(1000);
        uint64 t = uint64(bound(uint256(waitTime), 1, 365 days));

        vm.deal(actor, d);
        vm.prank(actor);
        c.Put{value: d}(0);
        vm.warp(1000 + t);

        vm.prank(actor);
        c.Collect(w);

        assertTrue(c.Acc(actor).balance == d - w);
    }
}

