pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 warpTo) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 ether, 1000 ether);
        vm.warp(bound(warpTo, 1, type(uint256).max / 2));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        // Immediately (same timestamp) the owner tries to withdraw everything.
        vm.prank(actor);
        c.Collect(amount);

        // A deposit made now can never be withdrawn at the same timestamp:
        // the full balance must remain locked in the contract.
        assertTrue(c.Acc(actor).balance == amount);
    }
}

