pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        lg = new Log();
        c = new C(address(lg));
    }

    function testFuzz_property(address actor, uint96 amount, uint _unlockTime) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint before = lg.History_length() == 0 ? 0 : lg.History_length();
        vm.deal(actor, uint256(amount));
        vm.prank(actor);
        c.Put{value: uint256(amount)}(_unlockTime);
        uint afterN = lg.History_length();
        (address s, string memory d, uint v, ) = lg.History(afterN - 1);
        assertTrue(s == actor && v == uint256(amount) && keccak256(bytes(d)) == keccak256(bytes("Put")));
    }
}
