// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Log lg;

    function setUp() public {
        c = new C(address(new Log()));
        // The Log was the first contract created by this test contract in setUp
        // (create nonce 0), so recover its address deterministically:
        lg = Log(_createdAt(address(this), 0));
    }

    function _createdAt(address deployer, uint64 /*nonce 0 -> rlp 0x80*/) internal view returns (address a) {
        // hard-code rlp for nonce 0: [0xd6, 0x94, deployer(20), 0x80]
        bytes memory m = abi.encodePacked(hex"d694", deployer, hex"80");
        assembly {
            a := shr(96, keccak256(add(m, 32), 23))
        }
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, 1e30);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool okCall, ) = address(c).call{value: amount}(
            abi.encodeWithSignature("Put(uint256)", unlockTime)
        );
        assertTrue(okCall, "Put should succeed for admissible input");

        // General rule: a completed Put by `actor` for `amount` is recorded as
        // the first message in the Log's History.
        bool recorded;
        address snd;
        uint256 val;
        try lg.History(0) returns (address s, string memory, uint256 v, uint256) {
            recorded = true;
            snd = s;
            val = v;
        } catch {
            recorded = false;
        }
        assertTrue(recorded && snd == actor && val == amount);
    }
}
